125		first, err := s.StartBatch("start-b1", "B1")
126		if err != nil {
127			t.Fatalf("首次开始执行应成功: %v", err)
128		}
129		checkFirstStartView(t, first)
130	
131		// 执行中登记两笔投料。
132		base := replayFeedTime()
133		if _, err := s.AddFeeding("f1", "B1", "M1", "100.5", base, "张三"); err != nil {
134			t.Fatalf("投料 f1 失败: %v", err)
135		}
136		if _, err := s.AddFeeding("f2", "B1", "M4", "2", base.Add(time.Hour), "李四"); err != nil {
137			t.Fatalf("投料 f2 失败: %v", err)
138		}
139	
140		// 批次已有投料、仍在执行中时重复提交首次开始请求：
141		// 返回的仍是首次开始时的原始结果（空投料、执行中），不重复状态变更。
142		replayExec, err := s.StartBatch("start-b1", "B1")
143		if err != nil {
144			t.Fatalf("投料后重放开始请求应成功: %v", err)
145		}
146		checkFirstStartView(t, replayExec)
147	
148		// 正常查询反映的是当前台账：执行中、已有 2 条投料与当前差额。
149		execView, err := s.GetBatch("B1")
150		if err != nil {
151			t.Fatalf("查询执行中批次失败: %v", err)
152		}
153		if execView.Status != StatusExecuting || execView.PlannedPortions != 3 ||
154			execView.RecipeVersion != "v2" {
155			t.Fatalf("当前批次应为执行中的 R1/v2、3 份，得到 %+v", execView)
156		}
157		if len(execView.Feedings) != 2 {
158			t.Fatalf("当前批次应已有 2 条投料，得到 %d 条", len(execView.Feedings))
159		}
160		execMats := materialsMap(execView)
161		checkRequirement(t, execMats, "M1", "750", "100.5", "-649.5")
162		checkRequirement(t, execMats, "M4", "6", "2", "-4")
163	
164		// 再登记一笔投料并关闭批次。
165		if _, err := s.AddFeeding("f3", "B1", "M1", "50", base.Add(2*time.Hour), "张三"); err != nil {
166			t.Fatalf("投料 f3 失败: %v", err)
167		}
168		if _, err := s.CloseBatch("close-b1", "B1"); err != nil {
169			t.Fatalf("关闭批次失败: %v", err)
170		}
171	
172		// 关闭后重复提交原来的开始请求：仍返回首次成功的原始结果，
173		// 不能重新执行状态变更，更不能把已关闭批次改回执行中。
174		replayClosed, err := s.StartBatch("start-b1", "B1")
175		if err != nil {
176			t.Fatalf("关闭后重放开始请求应成功: %v", err)
177		}
178		checkFirstStartView(t, replayClosed)
179		checkClosedCurrent(t, mustGetBatch(t, s, "B1"))
180	
181		// 再提交与再查询交替进行：重放结果始终是首次原始结果，
182		// 查询始终是已关闭的当前台账；重复提交前后台账保持不变。
183		replayAgain, err := s.StartBatch("start-b1", "B1")
184		if err != nil {
185			t.Fatalf("再次重放开始请求应成功: %v", err)
186		}
187		checkFirstStartView(t, replayAgain)
188		checkClosedCurrent(t, mustGetBatch(t, s, "B1"))
189	
190		// 重新打开台账后：重放仍返回首次开始时的原始结果，查询仍显示已关闭现状。
191		if err := s.Close(); err != nil {
192			t.Fatalf("关闭台账失败: %v", err)
193		}
194		s2, err := Open(dir)
195		if err != nil {
196			t.Fatalf("重新打开台账失败: %v", err)
197		}
198		t.Cleanup(func() { s2.Close() })
199	
200		replayAfterReopen, err := s2.StartBatch("start-b1", "B1")
201		if err != nil {
202			t.Fatalf("重新打开后重放开始请求应成功: %v", err)
203		}
204		checkFirstStartView(t, replayAfterReopen)
205		checkClosedCurrent(t, mustGetBatch(t, s2, "B1"))
206	}
207	
208	// 调用方修改首次开始返回对象中的状态、物料核对项或列表内容，
209	// 不能污染台账，也不能污染此后同一请求的重放结果；
210	// 再查询与再提交应各自反映应有的内容。
211	func TestStartBatchReplayResultIsCallerOwnedCopy(t *testing.T) {
212		s := openTestStore(t)
213		registerReplayRecipes(t, s)
214		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 5); err != nil {
215			t.Fatalf("创建批次失败: %v", err)
216		}
217		if _, err := s.UpdateDraftBatch("u-final", "B1", "R1", "v2", 3); err != nil {
218			t.Fatalf("调整草稿失败: %v", err)
219		}
220		first, err := s.StartBatch("start-b1", "B1")
221		if err != nil {
222			t.Fatalf("首次开始执行应成功: %v", err)
223		}
224		checkFirstStartView(t, first)
225	
226		// 随意污染调用方拿到的首次返回对象：状态、配方、份数、物料核对、
227		// 投料列表、新增伪造项。
228		first.Status = StatusClosed
229		first.PlannedPortions = 99
230		first.RecipeNo = "RX"
231		first.RecipeVersion = "v1"
232		first.RecipeName = "被污染的名称"
233		first.Feedings = append(first.Feedings, FeedingView{
234			Seq: 1, MaterialNo: "M1", Grams: "999", Time: replayFeedTime(), Registrar: "外人",
235		})
236		first.Materials[0].RequiredGrams = "1"
237		first.Materials[0].ActualGrams = "999"
238		first.Materials[0].DifferenceGrams = "998"
239		first.Materials = append(first.Materials, MaterialRequirement{MaterialNo: "FAKE"})
240	
241		// 再提交同一请求：重放结果必须仍是干净的首次原始结果。
242		replay, err := s.StartBatch("start-b1", "B1")
243		if err != nil {
244			t.Fatalf("污染首次返回对象后重放应成功: %v", err)
245		}
246		checkFirstStartView(t, replay)
247	
248		// 再查询：台账本身未被污染——执行中、最终计划、空投料、零实投。
249		got := mustGetBatch(t, s, "B1")
250		if got.Status != StatusExecuting || got.RecipeNo != "R1" ||
251			got.RecipeVersion != "v2" || got.RecipeName != "配方改版" ||
252			got.PlannedPortions != 3 {
253			t.Fatalf("台账被首次返回对象污染: %+v", got)
254		}
255		if len(got.Feedings) != 0 {
256			t.Fatalf("台账不应出现伪造投料，得到 %d 条: %+v", len(got.Feedings), got.Feedings)
257		}
258		gotMats := materialsMap(got)
259		if len(gotMats) != 2 {
260			t.Fatalf("台账物料项被污染，得到 %d 项: %+v", len(gotMats), got.Materials)
261		}
262		checkRequirement(t, gotMats, "M1", "750", "0", "-750")
263		checkRequirement(t, gotMats, "M4", "6", "0", "-6")
264	
265		// 再污染重放对象，第二轮再提交、再查询仍各自干净。
266		replay.Status = StatusDraft
267		replay.Materials[0].ActualGrams = "42"
268		replay.Feedings = append(replay.Feedings, FeedingView{Seq: 2, MaterialNo: "FAKE", Grams: "7"})
269		replay2, err := s.StartBatch("start-b1", "B1")
270		if err != nil {
271			t.Fatalf("污染重放对象后再次重放应成功: %v", err)
272		}
273		checkFirstStartView(t, replay2)
274		got2 := mustGetBatch(t, s, "B1")
275		if got2.Status != StatusExecuting || len(got2.Feedings) != 0 {
276			t.Fatalf("台账被重放对象污染: 状态=%s 投料数=%d", got2.Status, len(got2.Feedings))
277		}
278		got2Mats := materialsMap(got2)
279		checkRequirement(t, got2Mats, "M1", "750", "0", "-750")
280		checkRequirement(t, got2Mats, "M4", "6", "0", "-6")
281	}
282	
283	// 保留两种拒绝行为的区分：
284	//   - 换一个未使用的请求编号开始已经执行（或已关闭）的批次 → ErrInvalidState；
285	//   - 把首次成功的请求编号用于开始另一个仍为草稿的批次 → ErrRequestConflict
286	//     （操作相同但批次编号不同）。
287	// 被拒绝后，另一个批次仍是草稿，原批次的状态与投料也不受影响；
288	// 原成功请求仍可取得首次结果。
289	func TestStartBatchReplayRejections(t *testing.T) {
290		s := openTestStore(t)
291		registerReplayRecipes(t, s)
292		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 5); err != nil {
293			t.Fatalf("创建 B1 失败: %v", err)
294		}
295		if _, err := s.UpdateDraftBatch("u-final", "B1", "R1", "v2", 3); err != nil {
296			t.Fatalf("调整 B1 失败: %v", err)
297		}
298		// 另一个仍为草稿的批次 B2，沿用 R1/v1、7 份。
299		if _, err := s.CreateBatch("b2", "B2", "R1", "v1", 7); err != nil {
300			t.Fatalf("创建 B2 失败: %v", err)
301		}
302	
303		first, err := s.StartBatch("start-b1", "B1")
304		if err != nil {
305			t.Fatalf("首次开始 B1 应成功: %v", err)
306		}
307		checkFirstStartView(t, first)
308	
309		// 执行中：新请求编号再次开始 B1 → ErrInvalidState（不会被当成幂等重放）。
310		if _, err := s.StartBatch("start-fresh-executing", "B1"); !errors.Is(err, ErrInvalidState) {
311			t.Fatalf("新编号开始执行中的批次应返回 ErrInvalidState，得到 %v", err)
312		}
313		// 首次成功的编号用于开始另一个草稿批次 B2 → ErrRequestConflict。
314		if _, err := s.StartBatch("start-b1", "B2"); !errors.Is(err, ErrRequestConflict) {
315			t.Fatalf("同编号开始另一批次应返回 ErrRequestConflict，得到 %v", err)
316		}
317	
318		// 投料并关闭 B1。
319		base := replayFeedTime()
320		if _, err := s.AddFeeding("f1", "B1", "M1", "100.5", base, "张三"); err != nil {
321			t.Fatalf("投料 f1 失败: %v", err)
322		}
323		if _, err := s.AddFeeding("f2", "B1", "M4", "2", base.Add(time.Hour), "李四"); err != nil {
324			t.Fatalf("投料 f2 失败: %v", err)
325		}
326		if _, err := s.AddFeeding("f3", "B1", "M1", "50", base.Add(2*time.Hour), "张三"); err != nil {
327			t.Fatalf("投料 f3 失败: %v", err)
328		}
329		if _, err := s.CloseBatch("close-b1", "B1"); err != nil {
330			t.Fatalf("关闭 B1 失败: %v", err)
331		}
332	
333		// 已关闭：新编号开始 B1 → ErrInvalidState，绝不能改回执行中。
334		if _, err := s.StartBatch("start-fresh-closed", "B1"); !errors.Is(err, ErrInvalidState) {
335			t.Fatalf("新编号开始已关闭批次应返回 ErrInvalidState，得到 %v", err)
336		}
337		// 原成功编号用于 B2 仍是冲突。
338		if _, err := s.StartBatch("start-b1", "B2"); !errors.Is(err, ErrRequestConflict) {
339			t.Fatalf("关闭后同编号开始另一批次仍应返回 ErrRequestConflict，得到 %v", err)
340		}
341	
342		// 被拒绝后 B2 仍是原样草稿：R1/v1、7 份、无投料、零实投。
343		b2 := mustGetBatch(t, s, "B2")
344		if b2.Status != StatusDraft || b2.RecipeNo != "R1" || b2.RecipeVersion != "v1" ||
345			b2.RecipeName != "配方初版" || b2.PlannedPortions != 7 {
346			t.Fatalf("被拒绝后 B2 应仍是 R1/v1、7 份的草稿，得到 %+v", b2)
347		}
348		if len(b2.Feedings) != 0 {
349			t.Fatalf("B2 不应出现投料，得到 %d 条: %+v", len(b2.Feedings), b2.Feedings)
350		}
351		b2Mats := materialsMap(b2)
352		if len(b2Mats) != 2 {
353			t.Fatalf("B2 应仍是 v1 的 M1、M2 两种物料，得到 %d 项: %+v", len(b2Mats), b2.Materials)
354		}
355		checkRequirement(t, b2Mats, "M1", "0.875", "0", "-0.875") // 0.125 × 7
356		checkRequirement(t, b2Mats, "M2", "3.5", "0", "-3.5")     // 0.5 × 7
357	
358		// B1 仍是已关闭状态，投料与数量核对不变。
359		checkClosedCurrent(t, mustGetBatch(t, s, "B1"))
360	
361		// 原成功请求仍可取得首次开始时的原始结果。
362		replay, err := s.StartBatch("start-b1", "B1")
363		if err != nil {
364			t.Fatalf("拒绝后原成功请求仍应可重放: %v", err)
365		}
366		checkFirstStartView(t, replay)
367	}
368	
369	// mustGetBatch 查询批次，失败时立即终止测试。
370	func mustGetBatch(t *testing.T, s *Store, batchNo string) *BatchView {
371		t.Helper()
372		v, err := s.GetBatch(batchNo)
373		if err != nil {
374			t.Fatalf("查询批次 %q 失败: %v", batchNo, err)
375		}
376		return v
377	}
